// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(amount <= 1e30);
        // vary the randomness source through a fuzzed warp offset
        vm.warp(amount % 1000);

        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.play{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: whenever play() succeeds, pot is 0 (win) or exactly one ticket (loss).
        assertTrue(!ok || (c.pot() == 0 || c.pot() == 10));
    }
}
